    entry_requirements = '<div class="accordion__content" id="Entry_requirements-6" style="--panel-height: 637px;"> <p>The following criteria apply to students seeking admission to the Professional Doctorate program:</p><ul><li>The Pro Vice-Chancellor-Research, on the advice of the Dean of the School, determines admission to the Doctor of Education Award.</li><li>Applicants to the Doctor of Education Award are expected to satisfy the following criteria: <ul><li>Possession of a research Masters degree by thesis or dissertation appropriate to the professional field of the applicant; or</li><li>Possession of a Masters degree by coursework appropriate to the professional field of the applicant completed at a superior standard; or</li><li>Possession of a Bachelor’s degree with Honours (typically 1st Class or Class 2A Honours level or equivalent); or</li><li>Possession of a Master of Philosophy; or</li><li>In exceptional circumstances, an equivalent academic or professional background that is considered by the Dean of the School to be an appropriate preparation for independent study and research work at Doctoral level.</li></ul></li><li>An applicant may be required to satisfy the Dean of the School of the ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</li><li>In addition to the academic criteria listed above, applicants are normally expected to satisfy the following: <ul><li>have a minimum of 3 years of relevant professional practice;</li><li>have the support of an industry or professional mentor.</li></ul></li></ul><p>You may be required to demonstrate an ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-education%2Fpostgraduate%2Fdoctor-of-education&auth=N3OX2H5pTdpsB%2F%2FPeG2iOA&profile=programs&rank=120&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = '032064G';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 213px;"> <p>The Professional Doctorate is a research degree designed to meet the needs of professionals who aspire to achieve academic excellence and lead the development of knowledge within their profession. The program seeks to examine crucial topics and integrate professional experience with scholarly inquiry.</p><p>In particular, it aims to generate a research-based approach, providing answers to questions relevant to the professions or industry and encouraging a systematic way of collecting, analysing and interpreting data. For this reason, we recommend you seek the support of a relevant professional body, employer or industry group in defining your research area.</p> </div>',
    total_course_duration = '3 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-5" style="--panel-height: 565px;"> <p>The following criteria apply to students seeking admission to the Professional Doctorate program:</p><ul><li>The Pro Vice-Chancellor-Research, on the advice of the Dean of the School, determines admission to the Doctor of Health Sciences Award.</li><li>Applicants to the Doctor of Health Sciences Award are expected to satisfy the following criteria: <ul><li>Possession of a research Masters degree by thesis or dissertation appropriate to the professional field of the applicant; or</li><li>Possession of a Masters degree by coursework appropriate to the professional field of the applicant completed at a superior standard; or</li><li>Possession of a Bachelor’s degree with Honours (typically 1st Class or Class 2A Honours level or equivalent); or</li><li>Possession of a Master of Philosophy; or</li><li>In exceptional circumstances, an equivalent academic or professional background that is considered by the Dean of the School to be an appropriate preparation for independent study and research work at Doctoral level.</li></ul></li><li>In addition to the academic criteria listed above, applicants are normally expected to satisfy the following: <ul><li>have a minimum of 3 years of relevant professional practice;</li><li>have the support of an industry or professional mentor.</li></ul></li></ul><p>You may be required to demonstrate an ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-health-sciences%2Fpostgraduate%2Fdoctor-of-health-sciences&auth=QnNNzuxz%2BGHajpGIEQz6lg&profile=programs&rank=121&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = '074300J';


