UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 235px;"> <p>The Professional Doctorate is a research degree designed to meet the needs of professionals who aspire to achieve academic excellence and lead the development of knowledge within their profession. The program seeks to examine crucial professional topics and integrate professional experience with scholarly inquiry.</p><p>In particular, it aims to generate a research-based approach, providing answers to questions relevant to the professions or industry and encouraging a systematic way of collecting, analysing and interpreting data. For this reason, we recommend you seek the support of a relevant professional body, employer or industry group in defining your research area.</p> </div>',
    total_course_duration = '3 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-5" style="--panel-height: 543px;"> <p>The following criteria apply to students seeking admission to the Professional Doctorate program:</p><ul><li>The Pro Vice-Chancellor-Research, on the advice of the Dean of the School, determines admission to the Doctor of Physiotherapy Research Award.</li><li>Applicants to the doctoral program are expected to satisfy the following criteria: <ul><li>Possession of a research Masters degree by thesis or dissertation appropriate to the professional field of the applicant; or</li><li>Possession of a Masters degree by coursework appropriate to the professional field of the applicant completed at a superior standard; or</li><li>Possession of a Bachelor’s degree with Honours (typically 1st Class or Class 2A Honours level or equivalent); or</li><li>Possession of a Master of Philosophy; or</li><li>In exceptional circumstances, an equivalent academic or professional background that is considered by the Dean of the School to be an appropriate preparation for independent study and research work at Doctoral level.</li></ul></li><li>In addition to the academic criteria listed above, applicants are normally expected to satisfy the <ul><li>have a minimum of 3 years of relevant professional practice;</li><li>have the support of an industry or professional mentor.</li></ul></li></ul><p>You may be required to demonstrate an ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-health-sciences%2Fpostgraduate%2Fdoctor-of-physiotherapy-research&auth=nG3ZlzGyTgsIPCjthJS4Pg&profile=programs&rank=132&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = '075781A';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 174px;"> <p>A Doctor of Theology is a thesis-based research degree and is the civil counterpart to the Catholic Institute of Sydney’s ecclesiastical Doctor of Sacred Theology delivered at the Catholic Institute of Sydney. Students in the ThD benefit from an individually tailored program, that takes into account your background, the research methodology required, and the nature of your thesis topic. Candidates can pursue research training or further coursework as part of the Doctor of Theology program, and will benefit from ongoing support, mentoring and involvement in a vibrant research culture.</p> </div>',
    total_course_duration = '3 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 256px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" target="_blank">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/59634/Policy-Admission-and-Credit.pdf">Policy: <em>Admissions</em></a>.</p><p>Applications must also meet the following requirements:</p><ul><li>AQF7 in theology or equivalent and AQF9 in theology or equivalent with substantial research component at A High Level of Achievement. Or AQF8 Honours Degree in Theology with Honours at 1st or 2A Level OR equivalent.</li><li>For students without the prior study in the English language, IELTS of 7.0 in all bands.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-philosophy-and-theology%2Fpostgraduate%2Fdoctor-of-theology&auth=nShhbQT0ucwXFL0UzfEsZQ&profile=programs&rank=133&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '',
    total_course_duration = '0.5 years of equivalent full-time study. Only available part-time.',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-4" style="--panel-height: 344px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/admission-requirements">University’s minimum requirements for admission</a>.</p><p>To be eligible for admission to the Graduate Certificate (Ministry Leadership), applicants must meet the following additional requirements:</p><ol><li>have completed an AQF7 award in any field, or demonstrate at least 5 years of relevant professional experience, to be determined by the Arete Centre and the School of Philosophy and Theology.</li><li>Demonstrate that they are engaged in a form of church ministry that will form the basis of their theological reflection throughout the program</li><li>Provide a referee to the Arete Centre and be approved by the Arete Centre prior to enrolling at the University.</li></ol><p>Students need to be endorsed by the Arete Centre first, before applying to enrol into the program.</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-philosophy-and-theology%2Fpostgraduate%2Fgraduate-certificate-in-missionary-leadership&auth=XMiNr62p8D2mSVwpCgK88A&profile=programs&rank=134&query=%21FunDoesNotExist%3Apadrenull',
