UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 290px;"> <p>If you are devoted to including children with special learning needs in mainstream classrooms, this postgraduate program will build on your existing knowledge and experience. Our program will provide you with the skills and qualifications to become a specialist teacher or leader in special education.</p><p>Throughout your studies, you must complete four courses from a range that includes Educating Children with Special Needs, Teaching Students with Autism Spectrum Disorders, Behaviour Management and Social Skills Instruction and more.</p><p>Contact us today to be supported by academic staff who are specialists in their field and rigorous in-depth mentoring.</p><p>Graduates of this program may choose to enrol for a Master of Education at Notre Dame.</p> </div>',
    total_course_duration = '0.5 years full-time or part-time equivalent',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 367px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" target="_blank">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/59634/Policy-Admission-and-Credit.pdf">Policy: <em>Admissions</em></a>.</p><p>To be eligible for admission to the Graduate Certificate in Education applicants must also meet the following specific requirements:</p><ul><li>Hold a recognised four-year bachelor-level teaching qualification or equivalent, or</li><li>A recognised postgraduate teaching qualification, and</li><li>Have at least one year of relevant professional experience</li></ul><p>Applicants who have not successfully completed their secondary education in an English-speaking country will be required to sit the IELTS Academic Test and achieve a minimum overall score of 7.5 in IELTS Academic, with no score lower than 8.0 in speaking and listening and no score lower than 7.0 in reading and writing.</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-education%2Fpostgraduate%2Fgraduate-certificate-in-education&auth=c5yaTxJqTqbhVI6WUxVTCA&profile=programs&rank=144&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '',
    total_course_duration = '0.5 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 229px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" target="_blank">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/59634/Policy-Admission-and-Credit.pdf">Policy: <em>Admissions</em></a>.</p><p>Students must have a Bachelor or Postgraduate dgeree in teaching/education or a cognate discipline.</p><p>Applicants who hold current certification as a Highly Accomplished or Lead Teacher (HALT), as recognised by the Australian Institute for Teaching and School Leadership (AITSL), may be eligible for Fifty (50) units of credit of advanced standing in the Graduate Certificate in Education (Curriculum).</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-education%2Fpostgraduate%2Fgraduate-certificate-in-education-curriculum&auth=rGfcTMa239LoDrPogColFQ&profile=programs&rank=145&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 334px;"> <p>Are you interested in Early Childhood education? Our Graduate Certificate in Education (Early Childhood), which is delivered fully online, provides specialised study for those wishing to develop their skills and qualifications to teach in the early years from birth to 8 years.</p><p>This postgraduate program covers topics such as Understanding Holistic Development in Context, Early Years’ Curriculum Development, Trends in Early Childhood Development and Education, and Integration in Early Years settings.</p><p>If your current qualification is not in Early Childhood, you will also be required to complete a practical component that is embedded in the courses offered. This involves two weeks with babies and toddlers (aged 0-2 years) within a childcare context and 10 weeks with children aged 3-5 years within a school or childcare setting. The practicum components are embedded within the coursework.</p><p>Graduates of this program may choose to enrol for a Master of Education at Notre Dame.</p> </div>',
    total_course_duration = '0.5 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 560px;"> <p><strong>University Admission Requirements </strong></p><p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s Policy: Admission and Credit.</p><p><strong>Academic Requirements </strong></p><p>Academic requirements for admission to the Graduate Certificate in Education (Early Childhood) 4069 Graduate Certificate in Education (Early Childhood) Page 4 of 6 Effective Date: 12 July 2023 are:</p><ul type="disc"><li><strong>English Language Test Scores</strong> <br/> English Language Test Scores Education students who have English as an Additional language and are admitted on the basis of an International English Language Testing System (IELTS) assessment, or an equivalent English language proficiency assessment, are only admitted if they have attained an overall IELTS (or equivalent) score of 8.0 (with no score below 7 in any of the four skills areas and a score of no less than 8 in speaking and listening).</li></ul><p><strong>Specific Program Requirements for Admission</strong></p><p>To be eligible for admission to the Graduate Certificate in Education (Early Childhood) applicants must also meet the following specific requirements.</p><ul type="disc"><li>Hold an Initial Teacher Education degree in Early Childhood or Primary Education; and</li><li>Teacher Registration in Australia (called Accreditation in NSW)</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-education%2Fpostgraduate%2Fgraduate-certificate-in-education-early-childhood&auth=6zzyDP9uHvKbcSYx3L7FXw&profile=programs&rank=146&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '',
    total_course_duration = '0.5 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 677px;"> <p><strong>University Admission Requirements </strong></p><p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s Policy: Admission and Credit.</p><p><strong>Academic Requirements </strong></p><p>Academic requirements for admission to the Graduate Certificate in Education (Leadership and Management) 4071 Graduate Certificate in Education (Leadership and Management) Page 3 of 6 Effective Date: 1 January 2023 are:</p><ul type="disc"><li><strong>English Language Test Scores</strong> <br/> Education students who have English as an Additional language and are admitted on the basis of an International English Language Testing System (IELTS) assessment, or an equivalent English language proficiency assessment, are only admitted if they have attained an overall IELTS (or equivalent) score of 7.5 (with no score below 8.0 in speaking and listening, and no score lower than 7.0 reading and writing).</li></ul><p><strong>Specific Program Requirements for Admission</strong></p><p>To be eligible for admission to the Graduate Certificate in Education (Leadership and Management) applicants must also meet the following specific requirements</p><ul type="disc"><li>A Bachelor or postgraduate degree in teaching/education or a cognate discipline.</li></ul><p><strong>HALT Certification</strong></p><ul><li>Applicants who hold current certification as a Highly Accomplished or Lead Teacher (HALT), as recognised by the Australian Institute for Teaching and School Leadership (AITSL), may be eligible for Fifty (50) units of credit of advanced standing in the Graduate Certificate in Education (Leadership and Management).</li></ul> </div>',
