UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 290px;"> <p>If you are devoted to including children with special learning needs in mainstream classrooms, this postgraduate program will build on your existing knowledge and experience. Our program will provide you with the skills and qualifications to become a specialist teacher or leader in special education.</p><p>Throughout your studies, you must complete four courses from a range that includes Educating Children with Special Needs, Teaching Students with Autism Spectrum Disorders, Behaviour Management and Social Skills Instruction and more.</p><p>Contact us today to be supported by academic staff who are specialists in their field and rigorous in-depth mentoring.</p><p>Graduates of this program may choose to enrol for a Master of Education at Notre Dame.</p> </div>',
    total_course_duration = '0.5 year equivalent full-time study',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 146px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" target="_blank">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/59634/Policy-Admission-and-Credit.pdf">Policy: <em>Admissions</em></a>.</p><p>Students must have completed a Bachelor of Postgraduate in teaching/education or a cognate discipline.</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-education%2Fpostgraduate%2Fgraduate-certificate-in-education-special-and-inclusive-education&auth=08fCb4SV7%2FheiafZlvbzjg&profile=programs&rank=149&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 258px;"> <p>The Graduate Certificate in Health Leadership (GCHL) supports health professionals who want to consolidate or further their leadership career. The program provides students with a comprehensive introduction to the core principles of management and leadership within the complex health arena, in which consumers and their significant others play a central role. Students complete four core courses to support their development as a health professional leader and undertake peer coaching and a significant workplace project to demonstrate application of learning.</p><p>Should you wish to further your education, the Graduate Certificate in Health Leadership is an articulated qualification that forms the foundation for the nested postgraduate programs in the School of Medicine, the Graduate Diploma and the Master of Health Leadership and Education.</p> </div>',
    total_course_duration = '0.5 years full-time or equivalent part-time. Only available part-time.',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-4" style="--panel-height: 284px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" target="_blank">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/59634/Policy-Admission-and-Credit.pdf">Policy: <em>Admissions</em></a>.</p><p>To be eligible for admission to the Graduate Certificate in Health Leadership, applicants must meet the following specific requirements:</p><ul><li>As a minimum qualification, a recognised Bachelor degree in a health profession; or</li><li>A Bachelor degree in another (non-health) area with evidence of specific professional experience in health; or</li><li>Evidence of a senior management or leadership role in the health sector.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-medicine%2Fpostgraduate%2Fgraduate-certificate-in-health-leadership&auth=bEGsm%2B3hUTRtZOPJBWeKXA&profile=programs&rank=150&query=%21FunDoesNotExist%3Apadrenull',
