UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 296px;"> <p>This program comprises four courses covering the History of Philosophy from its ancient pre-Socratic roots to the present day. It is the only program in Australia that ensures that medieval philosophy is not overlooked, so that students have a strong sense not only of how modernity emerged, but also about key debates on the relationship between faith and reason.</p><p>Modern philosophy is studied in-depth, and students learn how the main distinctions made during that period affect contemporary philosophy. Covering both the analytic and the continental traditions of philosophy, the Contemporary Philosophy course gives students the tools to understand their current age. They will be well-prepared to continue their studies in Philosophy should they choose to do so.</p><p>This program can be taken as a stand-alone award. Students can also take these courses as a first step into a Graduate Diploma or Master of Arts in Philosophy, or Master of Liberal Arts.</p> </div>',
    total_course_duration = '0.5 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 85px;"> <p>Academic requirements for this program are outlined on our <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements">admission requirements</a> page. All applicants need to satisfy minimum requirements, including those relating to age and <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements/english-language-proficiency-requirements">English Language Proficiency</a>.</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-philosophy-and-theology%2Fpostgraduate%2Fgraduate-certificate-in-the-history-of-philosophy&auth=QY8NDkZRGP%2Fp4UY8%2FXDSqQ&profile=programs&rank=153&query=%21FunDoesNotExist%3Apadrenull',
