UPDATE courses SET
    course_description = '',
    total_course_duration = '0.5 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-4" style="--panel-height: 366px;"> <p style="text-align: left; text-indent: 0cm;"><strong>University Admission Requirements </strong></p><p style="text-align: left; text-indent: 0cm;">To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/admission-requirements" target="_blank">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s Policy: Admission and Credit</p><p style="text-align: left; text-indent: 0cm;"><strong> </strong></p><p style="text-align: left; text-indent: 0cm;"><strong>Specific Program Requirements for Admission</strong></p><p style="text-align: left; text-indent: 0cm;">To be eligible for admission to the Graduate Certificate in Modern Slavery and Human Trafficking applicants must also meet the following specific requirements:</p><p style="text-align: left; text-indent: 0cm;">Students must have as a minimum qualification, a recognised Bachelor degree (AQF level 7 qualification) or equivalent in any discipline area.</p><p style="text-align: left; text-indent: 0cm;">Applicants without a Bachelor level qualification may be eligible to enter the Program if they have at least two years’ experience in a related field. This would be determined on a case-by-case basis.</p> </div>',
