UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 242px;"> <p>This program was developed in partnership with St. Vincent’s Health Network Sydney to provide a career pathway for registered nurses to gain postgraduate qualifications in palliative care nursing. The Graduate Certificate in Palliative Care Nursing is designed to equip registered nurses with advanced knowledge and skills to provide high-quality, compassionate care to patients with life-limiting illnesses. Two courses in the program are led by industry experts, offering hands-on insights from clinical practice, while the remaining two courses are taught by Notre Dame''''s academic faculty, providing a robust theoretical foundation. This combination ensures students gain both practical skills and academic knowledge, preparing them for the evolving demands of healthcare. Graduates will be prepared to optimise patient outcomes, enhance quality of life, and support the well-being of both patients and their families across diverse healthcare settings.</p> </div>',
    total_course_duration = '0.5 year of equivalent full-time study.',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 229px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" title="Admissions requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s Policy: <em>Admissions</em>.</p><p>To be eligible for admission to the Graduate Certificate in Palliative Care Nursing applicants must also meet the following specific requirements:</p><ul><li>Current license to practice as a Registered Nurse with the Nursing and Midwifery Board of Australia, or provisional registration, which is applicable at the time of the student’s program commencement.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-nursing%2Fpostgraduate%2Fgraduate-certificate-in-palliative-care-nursing&auth=tmOOKX3qrduRZnfiuJoBTg&profile=programs&rank=161&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


