UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 235px;"> <p>The Graduate Certificate in the Practice of Ministry offers students a unique opportunity to study at an Ecclesiastical Faculty recognised by the Holy See. The program is designed to provide students with graduate-level grounding in the Practice of Christian Ministry. It is usually completed over the course of two years in which students will apply their prior theological learning to the field of pastoral ministry.</p><p>The Graduate Certificate in the Practice of Ministry represents an ideal qualification for those seeking to engage in pastoral ministry within the Church, particularly in the contexts of chaplaincy work, pastoral care programmes, spiritual direction, and safeguarding. Students in this program will gain the knowledge and skills to act with competence and ethical responsibility in the arena of pastoral practice.</p> </div>',
    total_course_duration = '0.5 years of equivalent full-time study. Only available part-time.',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 234px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/59634/Policy-Admission-and-Credit.pdf">Policy: <em>Admissions</em></a><em>.</em></p><p>To be eligible for admission to the Graduate Certificate in the Practice of Ministry applicants must also meet the following specific requirements.</p><ul><li>An AQF7 qualification in theology or equivalent qualification.</li><li>For students without the prior study in the English language, IELTS of 7.0 in all bands.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-philosophy-and-theology%2Fpostgraduate%2Fgraduate-certificate-in-the-practice-of-ministry&auth=4FIbsoJ%2FZ5eFmnQUJ3fJag&profile=programs&rank=164&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 174px;"> <p>The Graduate Certificate of Theological Studies is a six-month full-time (or equivalent part-time) foundational program that presents an opportunity for graduates from other fields to study Philosophy and Catholic Theology at master’s level at an Ecclesiastical Faculty and Catholic University. Students can select courses from the disciplines of Pastoral, Moral, Spiritual, Dogmatic, and Fundamental Theology, as well as Sacred Scripture, Church History, Patrology, Philosophy, Ministry Studies, Canon Law, Liturgical Studies, and related Ancient Languages.</p> </div>',
    total_course_duration = '0.5 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 229px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/59634/Policy-Admission-and-Credit.pdf">Policy: <em>Admissions</em></a><em>.</em></p><p>To be eligible for admission to the Graduate Certificate in Theological Studies, applicants must also meet the following specific requirements:</p><ul type="disc"><li>As a minimum qualification, a recognised Bachelor degree (AQF Level 7 qualification) or equivalent in any discipline area.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-philosophy-and-theology%2Fpostgraduate%2Fgraduate-certificate-in-theological-studies&auth=nhaeLD10sqTN4OWkMACTaw&profile=programs&rank=165&query=%21FunDoesNotExist%3Apadrenull',
