UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 251px;"> <p>If you are a Registered nurse who wishes to develop specialist skills and knowledge in the clinical nursing field, our postgraduate course is the qualification for you.</p><p>Notre Dame University Australia has partnered with leading healthcare providers to develop this unique one-year program for Registered Nurses. You must be employed with a participating health service provider and have the hospital''''s support to undertake this program.</p><p>Online units include Reflective Practice, Management and Ethics of Professional Life. Before enrolling in this program, you must have completed a Graduate Certificate in Clinical Nursing. Upon graduation, you can take a Master of Nursing (Clinical Nursing), which requires a further two semesters of part-time study.</p> </div>',
    total_course_duration = '1 year full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 228px;"> <p>The following entry requirements apply to this program:</p><ul><li>Current license to practice as a Registered Nurse with the Nursing and Midwifery Board of Australia or provisional registration, whichever is applicable at the time of commencement</li><li>Nursing or other appropriate degree or the equivalent</li><li>Minimum of one year relevant post registration nursing experience</li><li>Candidates must be employed with a participating health service provider and have their hospital''''s support to undertake the program.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-nursing%2Fpostgraduate%2Fgraduate-diploma-of-clinical-nursing&auth=p%2BnA9j2WIiKmh5FdUadB8Q&profile=programs&rank=169&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 318px;"> <p>Our Graduate Diploma of Computer Science combines core computer science theoretical knowledge with advanced practical skills. The curriculum focuses on in-demand skills such as software development, database systems, computer architecture design, project management and cyber security. These skills are crucial for tackling technological challenges and offer versatility across numerous sectors.</p><p>Notre Dame provides state-of-the-art facilities and cutting-edge technology, allowing you to apply theoretical knowledge in practical settings. Experienced faculty members bring real-world insights, and our strong industry partnerships ensure access to internships, industry projects and networking opportunities, giving you a competitive edge</p><p>With the tech industry’s rapid growth, graduates can expect diverse job opportunities and excellent career advancement potential. This degree equips you with essential skills for roles such as software engineer, data analyst and IT consultant.</p> </div>',
    total_course_duration = '1 year full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 144px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" target="_blank">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/59634/Policy-Admission-and-Credit.pdf">Policy: <em>Admissions</em></a>.</p><div><p paraeid="{5099f383-a1a6-45cb-8b60-334466211b4e}{133}" paraid="422446705">There are no additional entry requirements or pre-requisites for the Graduate Diploma of Computer Science award beyond the University’s minimum requirement for postgraduate admission.</p></div> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Farts-and-sciences%2Fpostgraduate%2Fgraduate-diploma-of-computer-science&auth=c7FexZC%2F9NbekXqoZqCtlg&profile=programs&rank=170&query=%21FunDoesNotExist%3Apadrenull',
