UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 235px;"> <p>The Graduate Diploma of Health Leadership and Education is designed to meet the unique learning needs of interprofessional health leaders and educators in a variety of healthcare settings and clinical and/or academic contexts. In acknowledging complex lives and multiple priorities this degree is flexible. Learners will extend their foundational knowledge and skills in leadership and educational theory and practice to explore their professional development in the context of their specific leadership and educational practice.</p><p>This qualification provides a pathway for health professionals to expand their leadership and educational knowledge, skills and effective learning. The Graduate Diploma of Health Leadership and Education is an articulated qualification that forms the foundation for the Master of Health Leadership and Education.</p> </div>',
    total_course_duration = '1 year equivalent full-time study. Only available part-time.',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-4" style="--panel-height: 173px;"> <p style="text-align: left; text-indent: 0cm;">To be eligible for admission to the Graduate Diploma of Health Leadership and Education applicants must meet the following specific requirements:</p><ul style="text-align: left;"><li>As a minimum qualification, a recognised Bachelor degree in a health profession; or</li><li>A Bachelor degree in another (non-health) area with evidence of specific professional experience in health; or</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-medicine%2Fpostgraduate%2Fgraduate-diploma-of-health-leadership-and-education&auth=nN%2FyCrMZLzjDRckYXz5tQQ&profile=programs&rank=172&query=%21FunDoesNotExist%3Apadrenull',
