UPDATE courses SET
    course_description = '',
    total_course_duration = '1 year full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-4" style="--panel-height: 405px;"> <p style="text-align: left; text-indent: 0cm;"><strong>University Admission Requirements </strong></p><p style="text-align: left; text-indent: 0cm;">To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/admission-requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s Policy: <em>Admissions</em></p><p style="text-align: left; text-indent: 0cm;"><strong> </strong></p><p style="text-align: left; text-indent: 0cm;"><strong>Specific Program Requirements for Admission</strong></p><p style="text-align: left; text-indent: 0cm;">To be eligible for admission to the Graduate Diploma of Modern Slavery and Human Trafficking, applicants must also meet the following specific requirements:</p><ul style="text-align: left;"><li>Students must have as a minimum qualification, a recognised Bachelor degree (AQF level 7 qualification) or equivalent in any discipline area.</li><li>Applicants without a Bachelor level qualification may be eligible to enter the Program if they have at least two years’ experience in a related field. This would be determined on a case-by-case basis.</li><li>Possession of a Graduate Certificate (AQF level 8 qualification) in Modern Slavery and Human Trafficking or a cognate discipline.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-law%2Fpostgraduate%2Fgraduate-diploma-of-modern-slavery-and-human-trafficking&auth=IVhOrudGbMBb0eIMf6w12Q&profile=programs&rank=177&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 229px;"> <p>If you have a desire to further your nursing career and advance the level at which you currently work, the Graduate Diploma of Nursing is designed to assist you to develop your expertise while working full-time in the field.</p><p>Our post-graduate qualification covers areas such as mental health, governance, management and leadership, education, acute care, evidence-based practice and research and professional development.</p><p>Consideration will be given to those who do not have a relevant degree but who have a wealth of nursing experience. Additional support will be offered to such applicants.</p> </div>',
    total_course_duration = '1 year full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 178px;"> <p>The following entry requirements apply to this program:</p><ul><li>Current license to practice as a Registered Nurse with the Nursing and Midwifery Board of Australia or provisional registration, whichever is applicable at the time of commencement</li><li>Nursing of other appropriate degree or the equivalent</li><li>Minimum of one year relevant post registration nursing experience.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-nursing%2Fpostgraduate%2Fgraduate-diploma-of-nursing&auth=WD3SnPwfkX3nvqcKmWgAGQ&profile=programs&rank=178&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 486px;"> <p>If you would like to further your nursing career and specialise in the perioperative care of patients the Graduate Diploma of Perioperative Nursing is designed for working professionals, such as you. If you enrol in this program, you will receive rigorous and demanding training from some of the best health providers in the country. Classes are held off-Campus at one of our partner health institutions in Western Australia.</p><p>Once you have completed this program, you may apply for a Master of Nursing (Perioperative), which requires a further year of study.</p><p>Our health service partners include:</p><ul><li aria-level="1" style="list-style-type:disc">Fiona Stanley and Fremantle Hospital Group</li><li aria-level="1" style="list-style-type:disc">King Edward Memorial Hospital</li><li aria-level="1" style="list-style-type:disc">Perth Children’s Hospital</li><li aria-level="1" style="list-style-type:disc">Sir Charles Gairdner Hospital</li><li aria-level="1" style="list-style-type:disc">St John of God Healthcare (Bunbury)</li><li aria-level="1" style="list-style-type:disc">St John of God Healthcare (Mt Lawley)</li><li aria-level="1" style="list-style-type:disc">St John of God Healthcare (Midland)</li><li aria-level="1" style="list-style-type:disc">St John of God Healthcare (Murdoch)</li><li aria-level="1" style="list-style-type:disc">St John of God Healthcare (Subiaco)</li></ul> </div>',
    total_course_duration = '1 year of equivalent full-time study',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 233px;"> <p>The following entry requirements apply to this program:</p><ul><li>Current license to practice as a Registered Nurse with the Nursing and Midwifery Board of Australia or provisional registration, whichever is applicable at the time of commencement</li><li>Nursing of other appropriate degree or the equivalent</li><li>Minimum of one year relevant post registration nursing experience</li><li>Currently working as a Registered Nurse in the perioperative environment of a partnership facility</li><li>Current employment contract for the term of the program with an approved health service.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-nursing%2Fpostgraduate%2Fgraduate-diploma-of-perioperative-nursing&auth=fkoNS15Ni%2F8I6PmC2kGyOQ&profile=programs&rank=179&query=%21FunDoesNotExist%3Apadrenull',
