UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 446px;"> <p>At The University of Notre Dame Australia, we provide postgraduate degrees in an atmosphere that emphasises the importance of community. Committed to excellence, the pursuit of a shared fulfilling life, the pastoral care of students and staff, we offer a uniquely personal approach to learning and teaching.</p><p>From its beginnings, Western philosophical thought has always emphasised the importance of the ‘examined life’ for valuing the whole person and promoting an ethical and informed way of living. Theology takes such investigation still further, by examining how God reveals himself to us, through Scripture and Tradition. In this degree, students are able to bring together faith and reason, to pursue a personally enriching program of study.</p><p>When undertaking the Graduate Diploma of Theological Studies, you will choose eight courses from the list published by our School of Philosophy &amp; Theology. Catholic Theology has developed with the history of the Church, becoming a rich field for the critical study and interpretation of Revelation, particularly in significance for the world.</p><p>Whether you are preparing for the Ministry or pastoral work, you will find that the Graduate Diploma of Theological Studies appeals both to experienced students and those whose interest in knowing the faith more has been ignited. Explore this subject with experienced lecturers and likeminded peers, enriching all aspects of your life through the study of the Catholic faith.</p> </div>',
    total_course_duration = '1 year full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 62px;"> <p>A Bachelor''''s degree in any discipline.</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-philosophy-and-theology%2Fpostgraduate%2Fgraduate-diploma-of-theological-studies&auth=uyGGEXKjORTZJmLBtMV7Kw&profile=programs&rank=181&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = '032058F';


