UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 189px;"> <p>A Master of Business Administration is the ideal degree for those who want to excel. Thanks to the superior skills and insights they bring to the workplace, MBA graduates often receive a significantly higher salary as well as a greater variety of career opportunities. For budding entrepreneurs, this program will show you how to launch, run, and grow your business.</p><p>The program allows you to advance your career while developing a network of business professionals. Compulsory courses cover foundational business concepts, and electives enable you to tailor the degree to your specific needs and interests.</p><p style="display:none;">The compulsory courses cover topics such as economics, accounting, financial management, marketing and strategic management. Students then choose four elective courses from an extensive range of options – this allows them to tailor the degree to their specific needs and interests.</p> </div>',
    total_course_duration = '2 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 399px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/admission-requirements"> University’s minimum requirements for admission for postgraduate programs</a>.</p><p><strong>Specific Program Requirements for Admission</strong></p><p>To be eligible for admission to the program, an applicant must hold:</p><ul><li>an AQF Level 7 qualification; or</li><li>studies sufficient to meet the requirements of an AQF Level 7 Award; or</li><li>informal/non-formal learning equivalent to an AQF Level 7 qualification plus evidence of the skills necessary to complete postgraduate studies.</li></ul><p>International students must have a qualification that is recognised as equivalent to an Australian Bachelor’s degree, AQF Level 7.</p><p>Applicants who have successfully completed subjects at another University, which are relevant to the selected program of study, may be eligible for <a href="https://www.notredame.edu.au/study/applications-and-admissions/recognition-of-prior-learning">Advanced Standing</a>.</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-business%2Fpostgraduate%2Fmaster-of-business-administration&auth=8qNtmL09nHOK8zJk%2BPhWJQ&profile=programs&rank=188&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = '110608H (Fremantle), 0100505 (Sydney)';


