UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 235px;"> <p>If you have been teaching for some time and have the practical experience and desire further to develop your education career with an Early Childhood focus, this Master’s degree is the course for you. The Master of Education (Early Childhood) is designed to meet the needs of professional teachers like you who wish to undertake further career development.</p><p>The program consists of eight courses: two compulsory, one elective and five specialisation courses. The Master of Education (Early Childhood) is a highly stimulating degree. With the guidance of experienced teachers, you develop the ability to critically analyse, design and implement proactive approaches to early childhood education.</p> </div>',
    total_course_duration = '1 year full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 423px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the University’s minimum requirements for admission. The requirements for admission are detailed in the University’s Policy: Admission and Credit.</p><p>To be eligible for admission to the Master of Education (Early Childhood) applicants must also meet the following specific requirements:</p><ul><li>Hold a Bachelor or postgraduate Initial Teacher Education degree in early childhood or<br/>primary education; and</li><li>Teacher Registration in Australia (called Accreditation in NSW)</li></ul><p><strong>English Language Test Scores</strong></p><p>Education students who have English as an additional language and are admitted on the basis of an International English Language Testing System (IELTS) assessment, or an equivalent English language proficiency assessment, are only admitted if they have attained an overall IELTS (or equivalent) score of 8.0 (with no score below 7 in any of the four skills areas and a score of no less than 8 in speaking and listening).</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-education%2Fpostgraduate%2Fmaster-of-education-early-childhood&auth=lSIXOIw06oPDln8WnHPFng&profile=programs&rank=195&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


