UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 370px;"> <p style="text-align: left;">The Master of Health Leadership and Education is designed to meet the unique learning needs of interprofessional health leaders and educators in a variety of healthcare settings and clinical and/or academic contexts. In acknowledging complex lives and multiple priorities this degree is flexible. Learners will extend their foundational knowledge and skills in leadership and educational theory and explore their professional development in the context of their specific leadership and educational practice. This qualification provides a pathway for the health professional interested in applying their leadership and educational practice to ultimately prepare for leading innovative and purposeful change in their health professional context.</p><p style="text-align: left;">The Postgraduate Medicine Associated Programs offers a nested suite of programs in the areas of Health Leadership and Health Professional Education, with multiple exit points. The nested programs provide an opportunity for students to complete and exit with a Graduate Certificate of either Health Leadership or Health Professional Education, and then build upon their studies through the completion of a unique Graduate Diploma or Master’s degree (by coursework) that combines both the Leadership and Education streams.</p> </div>',
    total_course_duration = '1.5 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-4" style="--panel-height: 173px;"> <p style="text-indent: 0cm;">To be eligible for admission to the Master of Health Leadership and Education applicants must meet the following specific requirements:</p><ul><li>As a minimum qualification, a recognised Bachelor degree in a health profession; or</li><li>A Bachelor degree in another (non-health) area with evidence of specific professional experience in health.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-medicine%2Fpostgraduate%2Fmaster-of-health-leadership-and-education&auth=uL%2FPXZAE3IOAZn%2Bx9ncbJg&profile=programs&rank=200&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 258px;"> <p style="text-align: left;">Candidates in the Master’s by Research program can undertake their research in either a full-time or a part-time capacity. The maximum time for completion of the Master’s by Research (not including periods of approved leave of absence) will normally be two years for a full-time student and four years for a part-time student. The minimum time for completion will normally be one year. The Master’s thesis is assessed by external examiners</p><p style="text-align: left;">Each candidate is required to have a minimum of two supervisors who will mentor and direct the candidate throughout the research phase and up to the point the thesis is put forward for examination. Before submitting an application, students are encouraged to contact the School of Health Sciences to arrange a discussion with a suitably qualified member of staff.</p> </div>',
    total_course_duration = '2 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 301px;"> <p style="text-align:justify">The following criteria are required for a student to be admitted to the Master’s by Research program:</p><ul><li>Completion of an undergraduate degree from a recognised university, which has been completed at a superior standard and which demonstrates the applicant’s potential to undertake and complete research-based study.</li><li>An equivalent academic background or extensive professional experience that is considered by the Dean of the School to be an appropriate preparation for independent study and research work at Master’s level.</li></ul><p>An applicant may be required to demonstrate an ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study or as deemed adequate by the Dean of the School.</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-health-sciences%2Fpostgraduate%2Fmaster-of-health-sciences&auth=NSgMkgyJfPiV89tdawscOg&profile=programs&rank=201&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = '065272E';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 280px;"> <p>A Master of Laws (LLM) is a great way to expand your legal knowledge and skills and differentiate yourself from other law graduates and lawyers. This program focuses on international law. With the globalisation of the legal profession, it is helpful to develop a strong understanding of international law and the practice of law in other jurisdictions.</p><p>The electives on offer may include Asia-Europe Trade Law, International Business Law and Dispute Resolution, International Cultural Heritage Law, International Business Law in Practice, International Taxation Law, International Transport Law, Issues in International Law and Contemporary Culture, International Environmental Law, The Legal Environment of the Asia- Pacific Region, The Philosophy of International Law, International Human Rights Law, International Perspectives on Bioethics and the Law, Law &amp; Religion, and Canon Law.</p> </div>',
    total_course_duration = '1 year full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 338px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/59634/Policy-Admission-and-Credit.pdf" target="_blank">University’s Policy: Admission and Credit</a>.</p><p>To be eligible for admission to the Master of Laws (Coursework) applicants must also meet the following specific requirements.</p><ul><li>Bachelor of Laws (LLB) or Diploma in Law (Law Extension Committee (NSW)) (DL) with a minimum credit average; or</li><li>LLB or DL with professional experience; or</li><li>LLB or DL with a Graduate Diploma in Legal Practice (or equivalent)</li><li>Juris Doctorate; or</li><li>International equivalents</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-law%2Fpostgraduate%2Fmaster-of-laws-coursework&auth=dPpczWruPGl0yMAWegPg9w&profile=programs&rank=202&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = '0101871';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 174px;"> <p>The Master of Laws by Research is a thesis-based research degree. You will work with a supervisor from the School’s academic staff to develop an appropriate topic within the areas of research focus for the School. The program is individually designed and built around the research and the topic to be investigated. A thesis submitted for a Master of Laws is expected to be systematic, written presentation of the results of study, investigation and research which makes a substantial contribution to the body of knowledge of the law in the relevant area.</p> </div>',
    total_course_duration = '2 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 323px;"> <p>To be eligible for admission to the Masters by Research, applicants must meet the following specific requirements:</p><ul><li>Possession of an undergraduate degree from a recognised University, which has been completed at a superior standard and which demonstrates the applicant’s potential to undertake and complete a research-based study at AQF level 9 equivalence.</li><li>In exceptional circumstances, an equivalent academic or professional background that is considered by the National Head of School to be an appropriate preparation for independent study and research work at Masters level.</li></ul><p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/59634/Policy-Admission-and-Credit.pdf" target="_blank">University’s Policy: Admission and Credit</a>.</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-law%2Fpostgraduate%2Fmaster-of-laws-research&auth=ljbYaQbRD959%2FFYQ0RBsRw&profile=programs&rank=203&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = '073036F';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 213px;"> <p>If you are already working in higher education and want to further your study, the Master of Learning and Teaching in Higher Education is the course for you. This flexible program is delivered online and is designed to engage you in a scholarly, evidence-based approach to teaching and learning.</p><p>You will be provided with the opportunity to cultivate research skills and investigate teaching and learning challenges relevant to your discipline. Individuals will use a systematic investigation of their practice to solve challenges and share results with peers. You will be able to choose electives to further your interests and career goals.</p> </div>',
    total_course_duration = '1.5 years equivalent full-time study. Only available part-time.',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 173px;"> <p>To be eligible for admission to the Master of Learning and Teaching in Higher Education applicants must meet the following specific requirements:</p><ul><li>Possession of a Bachelor’s award (AQF level 7 qualification) in any discipline area OR</li><li>Possession of a Graduate Diploma (AQF level 8 qualification) or equivalent in learning and teaching for higher education</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-education%2Fpostgraduate%2Fmaster-of-learning-and-teaching-in-higher-education&auth=%2BPoTSDEobkkQjDdHKbIaZg&profile=programs&rank=204&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 373px;"> <p>The Master of Liberal Arts provides a solid intellectual foundation and includes opportunities for students to engage in philosophical reasoning, ethical decision-making, and theological reflection in the Catholic tradition.</p><p>Our Master of Liberal Arts is designed as an entry award for which various exit pathways are available.</p><p>Successful completion of this course equips students with philosophical and theological skills derived from several hundred years of the Catholic Intellectual Tradition.</p><p>The program consists of 8 courses. Every student takes a course on Reason and Revelation, which is designed to help you see how philosophy and theology work together and to equip you to undertake your studies in philosophy and theology.</p><p>Then you can choose five more courses from a range of subjects in philosophy and theology, perhaps working toward a specialisation in Catholic Leadership. Finally, you will develop a supervised research project (worth two courses of your degree) in keeping with your interests and future career path.</p> </div>',
    total_course_duration = '1.5 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 266px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/59634/Policy-Admission-and-Credit.pdf" target="_blank">Policy: Admission and Credit</a>.</p><p>Applicants must possess a Graduate Certificate or higher in one of the following disciplines:</p><ul><li>Theology</li><li>Philosophy</li><li>Religious Education, or</li><li>A cognate discipline.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-philosophy-and-theology%2Fpostgraduate%2Fmaster-of-liberal-arts&auth=Cf1H%2FDQ1mGzsFeLWPZ3mCA&profile=programs&rank=205&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 386px;"> <p>Our Graduate Diploma and Master of Mathematics Education programs are designed to retrain accredited teachers from other disciplines in mathematics as a teaching area. Live online classes provide the opportunity to learn from lecturers and peers as role models of excellent teaching practice, network, ask questions and gain expert advice.</p><p>The programs will enable you to develop deep and flexible content knowledge in pure and applied tertiary-level mathematics. They will also allow you to build your mathematics pedagogy and enhance your capacity to engage your students to work mathematically to solve challenging, real-world problems across science, technology, engineering and mathematics (STEM) fields.</p><p>The Master of Mathematics Education will build capacity for research, data-informed teaching and leadership for a future head, highly accomplished or lead mathematics teachers. Qualified secondary mathematics teachers are in high demand across Australia. This program will improve your expertise and career prospects. It also fosters transferable skills such as critical reasoning, problem-solving, ethical judgement, and decision-making. The program has been designed around school terms to assist you in balancing existing work, family and other commitments.</p><!-- <p>Aimed at those who are already working in the primary and secondary education field, our Graduate Certificate in Mathematics program enables students to become proficient in pure and applied tertiary-level mathematics. You will also develop skills in analysing problems and developing innovative solutions, using technology to teach and enhance your communication and learning skills.</p> <p>Our part-time program has been specifically designed for working teachers who either want to improve their own mathematical expertise and career prospects or who would like to teach mathematics in the Catholic education system. The program consists of four core courses (Principles of Mathematics, Linear Algebra, Calculus and Statistics) and has been designed around your existing work, family and other commitments.</p>--> </div>',
    total_course_duration = '1.5 years equivalent full-time study. Only available part-time.',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 135px;"> <ul><li>Possession of a Bachelor’s award (AQF level 7 qualification) or equivalent in Initial Teacher Education; or</li><li>Possession of a Bachelor’s award (AQF level 7 qualification) and concurrent study in a Master of Teaching (AQF level 9 qualification)</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Farts-and-sciences%2Fpostgraduate%2Fmaster-of-mathematics-education&auth=wEKk9CD6HoXz3iJaToTxZw&profile=programs&rank=206&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 357px;"> <p>At The University of Notre Dame Australia, every research student is guided and advised by a member of staff who is a leader in their field. Your research supervisor will assist you in preparing your research proposal and will continue to mentor and guide your work until the completion of the degree.</p><p>The coursework component of the degree consists of four compulsory research-related subjects. These study modules will develop your competencies in critical analysis and scholarly writing, as well as provide ample opportunity for you to formulate substantial elements of the intended research.</p><p>For the program''''s research component, you will undertake a research project that significantly contributes to the medical field. The thesis will comprise the standard elements: an abstract, background and literature review, methods, results, discussion and conclusion. Similarly, the research dissertation will be based on a manuscript accepted for publication and comprises a literature review and findings.</p><p>By undertaking your postgraduate studies at the University, you will have the opportunity to further your research expertise and make a valuable contribution to the field of medicine.</p> </div>',
    total_course_duration = '1.5 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 205px;"> <p>The following criteria are required for a student to be admitted to the program:</p><ul><li>Possesses a medical degree from a recognised university.</li><li>Demonstrates potential to undertake and complete a research-based study.</li><li>Currently engaged in clinical or professional practice.</li><li>Satisfy the Dean of the School of the ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-medicine%2Fpostgraduate%2Fmaster-of-medicinesurgery&auth=950%2BJdhvBACuuSvfCyOW8g&profile=programs&rank=207&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = '083626A';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 296px;"> <p>Are you a senior nurse with a thesis subject you wish to research and specialise in? Taking a Graduate Certificate, Graduate Diploma, or Master of Nursing is an excellent career pathway for Registered Nurses who want to formalise their qualifications or develop specialist knowledge in a particular area of healthcare.</p><p>You can complete our Master of Nursing (Clinical Nursing) over two semesters of part-time study once you have completed the four Certificate and four Diploma courses. If you do not have a nursing degree, we will consider your accumulated experience when enrolling.</p><p>A research supervisor will assist you in choosing a thesis subject relevant to your specialist area of nursing practice. The supervisor will oversee the project to its completion. Call our postgraduate coordinator to discuss your options.</p> </div>',
    total_course_duration = '1.5 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 348px;"> <p>The program is open to you if you are a Registered Nurse who has a previous degree or you have accumulated a wealth of experience in nursing but do not have a degree.</p><p style="font-weight:bold;">English Language Requirements</p><p>You must be able to demonstrate two years of full-time secondary, vocational or tertiary level of study in Australia, Canada, New Zealand, Republic of Ireland, South Africa, United Kingdom or the United States of America. If you do not meet these requirements you will need to sit the Academic IELTS exam and achieve a score of at least 7.0 overall and 7.0 in each sub-section (reading, writing, listening and speaking) to qualify for entry into the Master of Nursing (Clinical Nursing). This applies to Permanent Residents and Australian citizens whose first language is not English and have not completed two years full-time academic study in Australia. IELTS results will need to be verified by the Admissions Office before an offer of a place can be made. The Admissions Office reserves the right to ask for IELTS results from any applicant. For more information, please visit <a href="https://www.ielts.org/" target="_blank" title="IELTS">www.ielts.org</a></p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-nursing%2Fpostgraduate%2Fmaster-of-nursing-clinical-nursing&auth=FG0Ow7jLGSPDM6T9xJlkLA&profile=programs&rank=208&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 455px;"> <p>If you are a Registered Nurse, a Master of Nursing is a useful career pathway if you want to formalise your qualifications or perhaps develop a specialist knowledge in a particular area of healthcare.</p><p>Our Master of Nursing (Coursework) can be completed over two semesters of part-time study once you have completed the four Certificate and four Diploma courses. Because you will choose a thesis subject relevant to your specialist area of nursing practice, you should discuss your study program with your postgraduate coordinator beforehand.</p><p>As with our other postgraduate programs, the Master of Nursing is aimed at practising Registered Nurses who wish to develop their knowledge and improve their skills so that they can operate at an advanced level. As a Master’s student, you will be allocated a research supervisor who will help you choose a relevant research subject and oversee the completion of the program.</p><p>The following specialisations are available for this course:</p><ul><li><a href="https://www.notredame.edu.au/programs/school-of-nursing/postgraduate/master-of-nursing-clinical-nursing">Master of Nursing (Clinical Nursing)</a></li><li><a href="https://www.notredame.edu.au/programs/school-of-nursing/postgraduate/master-of-nursing-executive-leadership">Master of Nursing (Executive Leadership)</a></li><li><a href="https://www.notredame.edu.au/programs/school-of-nursing/postgraduate/master-of-nursing-mental-health">Master of Nursing (Mental Health)</a></li><li><a href="https://www.notredame.edu.au/programs/school-of-nursing/postgraduate/master-of-nursing-perioperative-nursing">Master of Nursing (Perioperative Nursing)</a></li></ul> </div>',
    total_course_duration = '1.5 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 85px;"> <p>The program is open to you if you are a Registered Nurse who has a previous degree in Nursing or equivalent, and have a minimum of one-year relevant post-registration nursing experience.</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-nursing%2Fpostgraduate%2Fmaster-of-nursing-coursework&auth=cneHOcu8UxCi3ckT1wUtoQ&profile=programs&rank=209&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 312px;"> <p>If you are a career-focused practising nurse who desires to operate at a more senior level, the Master of Nursing (Leadership &amp; Management) is a valuable career pathway. In addition, you may wish to formalise your qualifications or develop specialist knowledge in a particular area of healthcare.</p><p>You can complete our Master of Nursing (Leadership and Management) over two semesters of part-time study. However, you will need to have completed a Graduate Certificate in Nursing Leadership and Management before enrolling in the Master''''s qualification.</p><p>You should discuss your study program with the School’s postgraduate coordinator beforehand – you will generally choose a thesis subject relevant to your specialist area of nursing practice.</p><p>As a Master’s student, you will be allocated a research supervisor who will help you choose a relevant research subject and oversee the completion of the program.</p> </div>',
    total_course_duration = '1.5 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 85px;"> <p>The program is open to you if you are a Registered Nurse who has a previous degree in Nursing or equivalent, and have a minimum of one-year relevant post-registration nursing experience.</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-nursing%2Fpostgraduate%2Fmaster-of-nursing-executive-leadership&auth=kN%2FtuGvwTI8NiLn%2FYkQVxQ&profile=programs&rank=210&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 274px;"> <p>If you are a Registered nurse with a desire to specialise in the challenging field of mental health our Master of Nursing (Mental Health) will be incredibly rewarding. You will be able to formalise your qualifications and develop your knowledge in mental health to deliver a higher level of care.</p><p>Completed in two semesters of part-time study the Master of Nursing (Mental Health) involves the delivery of a thesis in your area. If you do not have a degree qualification, we will take into account your accumulated experience when enrolling.</p><p>As a Master’s student, you will be allocated a research supervisor who will help you choose a relevant research subject and oversee the completion of the program. Get in touch with our postgraduate coordinator to discuss your options today.</p> </div>',
    total_course_duration = '1.5 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 341px;"> <p>The program is open to Registered Nurses who have a previous degree, or to those who do not have a degree but who have accumulated a wealth of experience in nursing.</p><p><strong>English Language Requirements</strong></p><p>You must be able to demonstrate two years of full-time secondary, vocational or tertiary level of study in Australia, Canada, New Zealand, Republic of Ireland, South Africa, United Kingdom or the United States of America. If you do not meet these requirements you will need to sit the Academic IELTS exam and achieve a score of at least 7.0 overall and 7.0 in each sub-section (reading, writing, listening and speaking) to qualify for entry into the Master of Nursing (Mental Health). This applies to Permanent Residents and Australian citizens whose first language is not English and have not completed two years full-time academic study in Australia. IELTS results will need to be verified by the Admissions Office before an offer of a place can be made. The Admissions Office reserves the right to ask for IELTS results from any applicant. For more information, please visit <a href="https://www.ielts.org/" target="_blank" title="IELTS">www.ielts.org</a></p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-nursing%2Fpostgraduate%2Fmaster-of-nursing-mental-health&auth=VA%2BbUu4EJcM1XdznDQ9FIQ&profile=programs&rank=211&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 312px;"> <p>Studying for a Master of Nursing is a valuable career pathway if you are a Registered Nurse and want to formalise your qualifications or develop specialist knowledge in a particular area of healthcare.</p><p>Our Master of Nursing (Perioperative Nursing) can be completed over two semesters of part-time study. You will have already completed a Graduate Diploma of Perioperative Nursing at Notre Dame’s Fremantle Campus. You should discuss your study program with the School’s postgraduate coordinator beforehand – you will generally choose a thesis subject relevant to your specialist area of nursing practice.</p><p>The Master of Nursing is designed to help you as a Registered Nurse by further developing your knowledge and improving your skills to operate at an advanced level.</p><p>As a Master’s student, you will be allocated a research supervisor who will help you choose a relevant research subject and oversee the completion of the program.</p> </div>',
    total_course_duration = '1 year part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 341px;"> <p>The program is open to you if you are a Registered Nurse with a previous degree or if you have no degree but have accumulated a wealth of experience in nursing.</p><p><strong>English Language Requirements</strong></p><p>You must be able to demonstrate two years of full-time secondary, vocational or tertiary level of study in Australia, Canada, New Zealand, Republic of Ireland, South Africa, United Kingdom or the United States of America. If you do not meet these requirements you will need to sit the Academic IELTS exam and achieve a score of at least 7.0 overall and 7.0 in each sub-section (reading, writing, listening and speaking) to qualify for entry into the Master of Nursing (Perioperative). This applies to Permanent Residents and Australian citizens whose first language is not English and have not completed two years full-time academic study in Australia. IELTS results will need to be verified by the Admissions Office before an offer of a place can be made. The Admissions Office reserves the right to ask for IELTS results from any applicant. For more information, please visit <a href="https://www.ielts.org/" target="_blank" title="IELTS">www.ielts.org</a></p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-nursing%2Fpostgraduate%2Fmaster-of-nursing-perioperative-nursing&auth=2sjuUPm9%2BBgm%2FGTi89vDSA&profile=programs&rank=212&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 280px;"> <p>Available as a full-time program across two calendar years (or equivalent part-time), our Master of Nursing (Research) will provide you with the research skills you need to support your professional practice. Topics covered include literature review, research methodology, ethics, analysis, verification and report writing. Furthermore, the program consists of several supervised research subjects, including research coursework as appropriate.</p><p>You will be expected to complete a substantial research project culminating in a thesis. Candidates will be assigned university-based supervisors who will provide support and academic guidance. Your supervisor will mentor and direct your studies throughout the research phase until your thesis is put forward for examination. Government support is available for domestic and international students, while domestic students may also apply for stipend scholarships awarded to students of exceptional potential.</p> </div>',
    total_course_duration = '2 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 345px;"> <p>In order to be considered for entry, applicants are expected to satisfy the following criteria:</p><ul><li>Current license to practice as a Registered Nurse within Australia or provisional registration whichever is applicable at the time of the students program commencement; or</li><li>Applicants who do not meet the requirements of the clause above, but are able to demonstrate equivalent international experience satisfy the criteria. In these circumstances, an applicant’s research topic may be limited to a non-clinical setting; and</li><li>Bachelor of Nursing or other appropriate degree; and</li><li>Minimum of two years relevant post registration nursing experience, or as acceptable by the program coordinator; and</li><li>An applicant may be required to satisfy the Dean of the School of Nursing and Midwifery of the ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-nursing%2Fpostgraduate%2Fmaster-of-nursing-research&auth=D1Yug7QoZLxCLOA462pAIw&profile=programs&rank=213&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = '073038D';


UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 700px;"> <p>It’s an exciting time for paramedicine, a fast-evolving health profession with demand from primary care, rural health and industrial health services. The two-year entry to practice Master of Paramedicine will develop paramedics for the future with the required knowledge, skills and professional attributes of paramedicine. Graduates will have broad industry-based experience in hospital, primary healthcare and ambulance jurisdictional services.</p><p>Drawing on national and international evidence-based perspectives of paramedic practice, the program provides opportunities for practice-based and work integrated learning with partners across the country. Students will engage in studies integrating critical analysis and inquiry across the breadth of paramedicine practice and graduate with the highest-calibre health and professional capabilities of a registered paramedic.</p><p>This program is specifically aligned to the professional capabilities for registered paramedics, as governed by the Australian Health Practitioner Regulation Agency (Ahpra). The program also adheres to the legislation governing paramedic practice, the Health Practitioner Regulation National Law.</p><p></p> </div>',
    total_course_duration = '2 years of equivalent full-time study',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-5" style="--panel-height: 417px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" title="Admission requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s Policy: <em>Admissions</em>.</p><p>To be eligible for admission to the Master of Paramedicine applicants must also meet the following specific requirements:</p><ul><li>A Bachelor of Nursing (or equivalent) and registration as a registered nurse with the Nursing and Midwifery Board of Australia; OR</li><li>A Bachelor of Biomedical Science; OR</li><li>A Bachelor degree with Human Anatomy and Physiology, and Human Pathophysiology (equivalent to at least 25 units of credit in each subject area); OR</li><li>A Graduate Degree with Human Anatomy and Physiology, and Human Pathophysiology (equivalent to at least 25 units of credit in each subject area) *</li></ul><p>*Pathway opportunities exist for students who do not meet these requirements. Refer to the <a href="https://www.notredame.edu.au/programs/school-of-medicine/postgraduate/graduate-certificate-in-medical-sciences">Graduate Certificate in Medical Science</a>.</p> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-medicine%2Fpostgraduate%2Fmaster-of-paramedicine&auth=8clpFF06cqEk1dxRA0cE9A&profile=programs&rank=214&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


