    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 351px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" title="Admission requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s Policy: <em>Admissions</em>.</p><p>To be eligible for admission to the Master of Philosophy applicants must also meet the following specific requirements.</p><ul><li>Possession of a Bachelor’s degree (AQF level 7 qualification); or Master of Philosophy</li><li>In exceptional circumstances, an equivalent academic or professional background that is considered by the National Head of School to be an appropriate preparation for independent study and research work at master’s level</li><li>An applicant may be required to satisfy the National Head of School of the ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-health-sciences%2Fpostgraduate%2Fmaster-of-philosophy-health-professional-education&auth=gBJNjl8Q0G5C0PlSamybFg&profile=programs&rank=218&query=%21FunDoesNotExist%3Apadrenull',
