    course_description = '',
    total_course_duration = '2 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-6" style="--panel-height: 279px;"> <p>The following criteria apply to students seeking admission to the Master of Research program:</p><ul><li>Possession of an undergraduate degree from a recognised university which has been completed at a superior standard and which demonstrates the applicant’s potential to undertake and complete research-based study at AQF level 9 equivalence.</li><li>In exceptional circumstances, an equivalent academic or professional background that is considered by the Dean of the School to be an appropriate preparation for independent study and research work at Master’s level.</li></ul><p>You may be required to demonstrate an ability to understand and communicate in both written and spoken English at a level adequate for the purpose of pursuing the program of study.</p> </div>',
