UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 446px;"> <p>The University of Notre Dame Australia’s Master of Speech Pathology (Qualifying) is a 2-year full-time program that prepares you to become an effective, culturally appropriate practitioner focusing on the Speech Pathologist-client relationship as part of collaborative multi-disciplinary practice. This program includes key Speech Pathology-specific courses and practice placement experiences meaning you are work-ready upon completion of the degree. There is an advanced and integrated focus on ethical and professional communication and behaviours.</p><p>Graduates of this program will have expertise in evidence-based and reflective practice fostering autonomous, adaptable practitioners who will be well prepared to meet the challenges of current and future health provision across diverse practice settings. This program has been purposely designed to meet the Accreditation Standards (2022) of Speech Pathology Australia.</p><p>You will develop assessment and intervention skills in laboratories, simulated learning environments and exposure to clients in Speech Therapy practices, schools, hospitals or community health settings in urban and rural locations.</p><p>The program also strongly focuses on evidence-based and reflective practice ensuring graduates will be well prepared to meet the challenges of current and future education and health provision across the many practice areas in which Speech Pathologists are employed.</p> </div>',
    total_course_duration = '2 years equivalent full-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 333px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" title="Admission requirements">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s Policy: <em>Admissions</em>.</p><p>To be eligible for admission to the Master of Speech Pathology (Qualifying) applicants must also meet the following specific requirements:</p><ul><li>A Bachelor of Health (or Health Science) with a minimum GPA of 2.5; OR</li><li>Any Bachelor degree in another related field with a minimum GPA of 2.5</li><li>Any inherent requirements or components (such as evidence of performance capability in a particular field of study) that need to be met to ensure that the academic requirements and integrity of a Program or Course are maintained.</li><li>An alternative pathway for Aboriginal and Torres Strait Islander applicants is applicable for this award</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-health-sciences%2Fpostgraduate%2Fmaster-of-speech-pathology-qualifying&auth=DmR5prSIfQEF1vVbwlyiSw&profile=programs&rank=234&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


