UPDATE courses SET
    course_description = '<div class="accordion__content" id="Why_study_this_degree-1" style="--panel-height: 242px;"> <p>The Master of Theology is an 18-month full-time (or equivalent part-time) advanced degree in theology that allows studies to tailor their learning by choosing from one of the three study streams in the program. The Advanced (Research) stream prepares students for further study in theology. It involves advanced coursework and a thesis and can prepare students for teaching theology and for a Higher Degree by Research (ThD or PhD) in theology. The Pastoral Studies, or Practice of Ministry Stream, enables those who have completed the Graduate Certificate in the Practice of Ministry to extend their learning into the master’s level. This pathway includes advanced coursework and a research component. The General Studies Stream caters to those who want to expand their knowledge via a broad selection of advanced coursework without a major research component.</p> </div>',
    total_course_duration = '1.5 years full-time or equivalent part-time',
    offshore_tuition_fee = '',
    entry_requirements = '<div class="accordion__content" id="Entry_requirements-3" style="--panel-height: 333px;"> <p>To be eligible for admission to The University of Notre Dame Australia, all applicants must meet the <a href="https://www.notredame.edu.au/study/applications-and-admissions/admission-requirements" target="_blank">University’s minimum requirements for admission</a>. The requirements for admission are detailed in the University’s <a href="https://www.notredame.edu.au/__data/assets/pdf_file/0027/59634/Policy-Admission-and-Credit.pdf">Policy: <em>Admissions</em></a>.</p><p>Applications must also meet the following requirements:</p><ul><li>Advanced (Research) Stream: AQF7 in theology or MDiv. GPA of 2.5 overall, with WAM of at least 70% (Distinction, on UNDA scale, or equivalent) in the intended field of research across at least 100 credits in that discipline.</li><li>Practice of Ministry Stream: AQF7 in Theology or MDiv with 2.0GPA and the Graduate Certificate in the Practice of Ministry with at least a Credit or better in all courses</li><li>General Studies Stream: AQF7 in theology or MDiv. At minimum of 2.0 GPA.</li><li>For students without the prior study in the English language, IELTS of 7.0 in all bands.</li></ul> </div>',
    apply_form = 'https://und-search.funnelback.squiz.cloud/s/redirect?collection=und~sp-program&url=https%3A%2F%2Fwww.notredame.edu.au%2Fprograms%2Fschool-of-philosophy-and-theology%2Fpostgraduate%2Fmaster-of-theology&auth=sa0rGlQ4icrhu70yz0jSpA&profile=programs&rank=236&query=%21FunDoesNotExist%3Apadrenull',
    created_at = '2026-06-26 23:37:52',
    updated_at = '2026-06-26 23:37:52'
WHERE cricos_course_code = 'UNKNOWN';


